 1→import { test } from "node:test";
 2→import assert from "node:assert/strict";
 3→import { planVisibility, renderPlan, HIDDEN } from "./plan-visibility.mjs";
 4→
 5→const WRONG = "skl-sZFb3KatWY6m", RIGHT = "skl-oBaDO5CceKnr", PEND = "skl-pending";
 6→
 7→const baseline = {
 8→  assets: {
 9→    [WRONG]: { baseline_visibility: "team" },
10→    [RIGHT]: { baseline_visibility: "team" },
11→    [PEND]: { baseline_visibility: "team" },
12→  },
13→  decisions: [
14→    { asset_id: WRONG, decision: "reject", reasons: ["rule reject: a corrected record exists (reason=wrong)"] },
