  1→/**
  2→ * Gate baseline (P4-4b): freeze the evidence and decisions that every run of
  3→ * the on/off comparison starts from.
  4→ *
  5→ * Why a frozen baseline instead of deciding live before each run: if the gate
  6→ * learned from run 1 and run 2 before run 3, the third gate-on run would face
  7→ * a different gate from the first, and the two arms would no longer share an
  8→ * initial condition. The difference between arms could then be the gate, or
  9→ * the order the runs happened in. So the preparation runs' events are frozen
 10→ * here once, the decisions are computed once, and apply.sh resets to this
 11→ * before every run. Nothing a comparison run produces feeds back into it.
 12→ *
 13→ * Inputs are run directories from run-once.sh. Each contributes its
 14→ * events.jsonl (fetched), used-events.jsonl (used) and outcome-events.jsonl
 15→ * (validated / corrected / needs_review). If a run predates the outcome judge,
 16→ * its outcomes are computed here from used-events + verdict + tokens, and the
 17→ * baseline says so.
 18→ *
 19→ * Usage:
 20→ *   node evaluation/gate/build-baseline.mjs --runs=<dir,dir,...> --snapshot=<asset-pool-snapshot.json>
 21→ *        [--visibility=<current.json from apply.sh --status>] [--tokens=F] [--decoys=F] [--now=ISO]
 22→ *        [--out=evaluation/gate/artifacts/gate_baseline.json]
 23→ */
 24→
 25→import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
 26→import { basename, dirname, join } from "node:path";
 27→import { fileURLToPath } from "node:url";
 28→import { parseJsonl } from "../provenance/build-events.mjs";
 29→import { judgeOutcome } from "../attribution/judge-outcome.mjs";
 30→import { decide } from "./decide.mjs";
 31→import { renderDecisions } from "./render-decision.mjs";
 32→
 33→const HERE = dirname(fileURLToPath(import.meta.url));
 34→export const DEFAULT_OUT = join(HERE, "artifacts", "gate_baseline.json");
 35→
 36→function readJsonl(path) {
 37→  return existsSync(path) ? parseJsonl(readFileSync(path, "utf8")) : [];
 38→}
 39→function readJson(path, fallback = null) {
 40→  return existsSync(path) ? JSON.parse(readFileSync(path, "utf8")) : fallback;
 41→}
 42→
 43→/** Collect one run directory's events; compute outcomes if the run has none on disk. */
 44→export function collectRun(dir, { tokensByAsset }) {
 45→  const runJson = readJson(join(dir, "run.json"), {});
 46→  const fetched = readJsonl(join(dir, "events.jsonl"));
 47→  const used = readJsonl(join(dir, "used-events.jsonl"));
 48→  let outcomes = readJsonl(join(dir, "outcome-events.jsonl"));
 49→  let outcomeSource = "outcome-events.jsonl";
 50→  if (outcomes.length === 0 && used.length > 0) {
 51→    const verdictDoc = readJson(join(dir, "verdict.json"), { verdict: "ERROR", attempts: [] });
 52→    const tokens = readJson(join(dir, "tokens.json"), tokensByAsset);
 53→    outcomes = judgeOutcome({ usedEvents: used, verdictDoc, tokensByAsset: tokens }).events;
 54→    outcomeSource = "computed here by judge-outcome from used-events.jsonl + verdict.json";
 55→  }
 56→  return {
 57→    run_id: runJson.run_id ?? basename(dir),
 58→    label: runJson.label ?? null,
 59→    verdict: runJson.verdict ?? null,
 60→    started_at: runJson.started_at ?? null,
 61→    outcome_source: outcomeSource,
 62→    events: [...fetched, ...used, ...outcomes],
 63→  };
 64→}
 65→
 66→export function buildBaseline({ runs, snapshot, visibility = null, tokensByAsset = {}, decoys = [], now }) {
 67→  const frozenAt = now ?? new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
 68→  const seen = new Map();
 69→  const sourceRuns = [];
 70→  for (const r of runs) {
 71→    const ids = [];
 72→    for (const e of r.events) {
 73→      if (!seen.has(e.event_id)) { seen.set(e.event_id, e); ids.push(e.event_id); }
 74→    }
 75→    sourceRuns.push({ run_id: r.run_id, label: r.label, verdict: r.verdict, started_at: r.started_at, outcome_source: r.outcome_source, event_ids: ids });
 76→  }
 77→  const events = [...seen.values()];
 78→  const decisions = decide({ events, snapshot, decoys, now: frozenAt, tokensByAsset });
 79→
 80→  const assets = {};
 81→  for (const a of snapshot.assets ?? []) {
 82→    const vis = visibility?.[a.asset_id] ?? null;
 83→    assets[a.asset_id] = {
 84→      name: a.name ?? null,
 85→      version: a.version ?? null,
 86→      producer_user_id: a.producer_user_id ?? null,
 87→      producer_agent_id: a.producer_agent_id ?? null,
 88→      // The pool as entered: every scenario asset is team-visible (enter-pool.sh
 89→      // checks it). If the live value was supplied it is recorded as read; if
 90→      // not, "team" is the contract and the source says it was not read.
 91→      baseline_visibility: vis ?? "team",
 92→      visibility_source: vis ? "read from /v3/meta/asset/get at freeze time" : "enter-pool.sh contract (not read at freeze time)",
 93→    };
 94→  }
 95→
 96→  return {
 97→    schema_version: "gate-baseline-v1",
 98→    frozen_at: frozenAt,
 99→    pool_snapshot_at: snapshot.pool_snapshot_at ?? null,
100→    team_id: snapshot.team_id ?? null,
101→    source_runs: sourceRuns,
102→    event_count: events.length,
103→    by_state: events.reduce((acc, e) => { acc[e.state] = (acc[e.state] ?? 0) + 1; return acc; }, {}),
104→    assets,
105→    decisions,
106→    events,
107→    note: "Every comparison run resets to this baseline before it starts (apply.sh --reset / --apply). "
108→        + "Runs listed in source_runs are the evidence base and are not part of the comparison.",
109→  };
110→}
111→
112→export function renderBaseline(b) {
113→  const lines = [`# Gate baseline — frozen ${b.frozen_at}`, ""];
114→  lines.push(`pool frozen ${b.pool_snapshot_at}, team ${b.team_id}`);
115→  lines.push(`evidence: ${b.event_count} event(s) from ${b.source_runs.length} preparation run(s)`);
116→  for (const r of b.source_runs) lines.push(`  ${r.run_id}  ${r.verdict ?? "?"}  ${r.event_ids.length} event(s)  outcomes: ${r.outcome_source}`);
117→  lines.push(`by state: ${Object.entries(b.by_state).map(([k, v]) => `${k} ${v}`).join(", ")}`);
118→  lines.push("", "assets at baseline:");
119→  for (const [id, a] of Object.entries(b.assets)) lines.push(`  ${id}  ${a.name ?? ""}  v${a.version ?? "?"}  visibility=${a.baseline_visibility} (${a.visibility_source})`);
120→  lines.push("", renderDecisions(b.decisions));
121→  return lines.join("\n");
122→}
123→
124→if (import.meta.url === `file://${process.argv[1]}`) {
125→  const arg = (name) => { const a = process.argv.find((x) => x.startsWith(`--${name}=`)); return a ? a.slice(name.length + 3) : null; };
126→  const runsArg = arg("runs"); const snapshotArg = arg("snapshot");
127→  if (!runsArg || !snapshotArg) {
128→    console.error("usage: node build-baseline.mjs --runs=<dir,dir> --snapshot=F [--visibility=F] [--tokens=F] [--decoys=F] [--now=ISO] [--out=F]");
129→    process.exit(2);
130→  }
131→  const tokensByAsset = arg("tokens") ? readJson(arg("tokens"), {}) : {};
132→  const runs = runsArg.split(",").filter(Boolean).map((d) => collectRun(d, { tokensByAsset }));
133→  const baseline = buildBaseline({
134→    runs,
135→    snapshot: readJson(snapshotArg),
136→    visibility: arg("visibility") ? readJson(arg("visibility")) : null,
137→    tokensByAsset,
138→    decoys: arg("decoys") ? readJson(arg("decoys"), []) : [],
139→    now: arg("now") ?? undefined,
140→  });
141→  const out = arg("out") ?? DEFAULT_OUT;
142→  mkdirSync(dirname(out), { recursive: true });
143→  writeFileSync(out, JSON.stringify(baseline, null, 2) + "\n");
144→  console.log(renderBaseline(baseline));
145→  console.log(`\n→ ${out}`);
146→}
